<script setup lang="ts">import{ref}from'vue';import{useMutation,useQuery,useQueryClient}from'@tanstack/vue-query';import{adminApi,type Role,type RoleInput}from'../api';import RoleDialog from'../components/RoleDialog.vue';import DsBadge from'@/shared/ui/DsBadge.vue';import DsButton from'@/shared/ui/DsButton.vue';import DsCard from'@/shared/ui/DsCard.vue';import DsPageHeader from'@/shared/ui/DsPageHeader.vue';import DsState from'@/shared/ui/DsState.vue';const qc=useQueryClient(),selected=ref<Role|null>(null),open=ref(false);const q=useQuery({queryKey:['admin','roles'],queryFn:adminApi.roles});const permissions=useQuery({queryKey:['admin','permissions'],queryFn:adminApi.permissions});const save=useMutation({mutationFn:(v:RoleInput)=>selected.value?adminApi.updateRole(selected.value.Code,v):adminApi.createRole(v),onSuccess:async()=>{open.value=false;selected.value=null;await qc.invalidateQueries({queryKey:['admin','roles']})}});function edit(r:Role){selected.value=r;open.value=true}</script><template><section><DsPageHeader eyebrow="ACCESS CONTROL" title="Role Management" description="Define reusable permission sets for application users."><template #actions><DsButton @click="selected=null;open=true">Add role</DsButton></template></DsPageHeader><DsState v-if="q.isPending.value" kind="loading"/><DsState v-else-if="q.isError.value" kind="error" title="Unable to load roles"/><div v-else class="grid"><DsCard v-for="r in q.data.value" :key="r.Code"><div class="row"><h3>{{r.Name}}</h3><DsBadge v-if="r.IsSystem">System</DsBadge></div><code>{{r.Code}}</code><p>{{r.Description||'No description provided.'}}</p><div class="foot"><small>{{r.Permissions?.length??0}} permissions</small><DsButton variant="secondary" @click="edit(r)">Edit</DsButton></div></DsCard></div><RoleDialog :open="open" :role="selected" :permissions="permissions.data.value??[]" :busy="save.isPending.value" @close="open=false" @save="save.mutate"/></section></template><style scoped>section{padding:32px}.grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(280px,1fr));gap:16px}.row,.foot{display:flex;justify-content:space-between;gap:12px;align-items:center}.foot{margin-top:18px}h3{margin:0}code,small,p{color:var(--ds-text-secondary)}@media(max-width:640px){section{padding:20px}}</style>